-- Datos maestros propios de Mayorista. Aplicar únicamente en QA independiente.
begin;
alter table mayorista_private.usuarios add nombre text not null default '';
create table mayorista_private.user_commands(empresa_id uuid not null,comando_id uuid not null,actor_id uuid not null,huella text not null,respuesta jsonb not null,creado_en timestamptz not null default now(),primary key(empresa_id,comando_id));
revoke all on mayorista_private.user_commands from public,anon,authenticated;
create table mayorista.rutas(empresa_id uuid not null,ruta_id uuid not null,nombre text not null,zona text not null,primary key(empresa_id,ruta_id));
create table mayorista.listas(empresa_id uuid not null,lista_id uuid not null,nombre text not null,activa boolean not null default true,primary key(empresa_id,lista_id));
alter table mayorista.clientes add direccion text not null default '';
alter table mayorista.clientes add latitud numeric check(latitud between -90 and 90);
alter table mayorista.clientes add longitud numeric check(longitud between -180 and 180);
alter table mayorista.clientes add lista_id uuid;
alter table mayorista.clientes add foreign key(empresa_id,ruta_id) references mayorista.rutas(empresa_id,ruta_id);
alter table mayorista.clientes add foreign key(empresa_id,lista_id) references mayorista.listas(empresa_id,lista_id);
alter table mayorista.precios add lista_id uuid;
alter table mayorista.precios add presentacion text not null default 'unidad' check(presentacion in ('unidad','pack','caja','bulto'));
alter table mayorista.precios add foreign key(empresa_id,lista_id) references mayorista.listas(empresa_id,lista_id);
create table mayorista.ofertas(empresa_id uuid not null,oferta_id uuid not null,precio_id uuid not null,nombre text not null,descuento integer not null check(descuento between 1 and 99),desde timestamptz not null,hasta timestamptz not null,primary key(empresa_id,oferta_id),foreign key(empresa_id,precio_id) references mayorista.precios(empresa_id,precio_id),check(hasta>desde));
create table mayorista.objetivos(empresa_id uuid not null,vendedor_id uuid not null,periodo text not null check(periodo ~ '^20[0-9]{2}-(0[1-9]|1[0-2])$'),centavos bigint not null check(centavos>0),visitas integer not null check(visitas>0),primary key(empresa_id,vendedor_id,periodo),foreign key(empresa_id,vendedor_id) references mayorista.vendedores(empresa_id,vendedor_id));
create table mayorista.catalog_control(empresa_id uuid primary key,revision integer not null check(revision>=0));
-- La asignación actual puede cambiar sin reescribir el vendedor histórico del pedido/visita.
alter table mayorista.pedidos drop constraint pedidos_empresa_id_cliente_id_vendedor_id_fkey;
alter table mayorista.pedidos add foreign key(empresa_id,cliente_id) references mayorista.clientes(empresa_id,cliente_id);
alter table mayorista.pedidos add foreign key(empresa_id,vendedor_id) references mayorista.vendedores(empresa_id,vendedor_id);
alter table mayorista.visitas drop constraint visitas_empresa_id_cliente_id_vendedor_id_fkey;
alter table mayorista.visitas add foreign key(empresa_id,cliente_id) references mayorista.clientes(empresa_id,cliente_id);
alter table mayorista.visitas add foreign key(empresa_id,vendedor_id) references mayorista.vendedores(empresa_id,vendedor_id);
alter table mayorista.rutas enable row level security;alter table mayorista.rutas force row level security;
alter table mayorista.listas enable row level security;alter table mayorista.listas force row level security;
alter table mayorista.ofertas enable row level security;alter table mayorista.ofertas force row level security;
alter table mayorista.objetivos enable row level security;alter table mayorista.objetivos force row level security;
alter table mayorista.catalog_control enable row level security;alter table mayorista.catalog_control force row level security;
create policy rutas_admin on mayorista.rutas for all to authenticated using(mayorista.operador(empresa_id,array['gerencia','administracion'])) with check(mayorista.operador(empresa_id,array['gerencia','administracion']));
create policy rutas_vendedor on mayorista.rutas for select to authenticated using(mayorista.operador(empresa_id,array['vendedor']) and exists(select 1 from mayorista.clientes c where c.empresa_id=rutas.empresa_id and c.ruta_id=rutas.ruta_id));
create policy listas_read on mayorista.listas for select to authenticated using(mayorista.operador(empresa_id,array['gerencia','administracion','vendedor']));
create policy listas_write on mayorista.listas for all to authenticated using(mayorista.operador(empresa_id,array['gerencia','administracion'])) with check(mayorista.operador(empresa_id,array['gerencia','administracion']));
create policy ofertas_read on mayorista.ofertas for select to authenticated using(mayorista.operador(empresa_id,array['gerencia','administracion','vendedor']));
create policy ofertas_write on mayorista.ofertas for all to authenticated using(mayorista.operador(empresa_id,array['gerencia','administracion'])) with check(mayorista.operador(empresa_id,array['gerencia','administracion']));
create policy objetivos_read on mayorista.objetivos for select to authenticated using(mayorista.operador(empresa_id,array['gerencia','administracion']) or mayorista.operador(empresa_id,array['vendedor']) and exists(select 1 from mayorista.miembros m where m.empresa_id=objetivos.empresa_id and m.user_id=(select auth.uid()) and m.vendedor_id=objetivos.vendedor_id));
create policy objetivos_write on mayorista.objetivos for all to authenticated using(mayorista.operador(empresa_id,array['gerencia','administracion'])) with check(mayorista.operador(empresa_id,array['gerencia','administracion']));
create policy catalog_control_admin on mayorista.catalog_control for all to authenticated using(mayorista.operador(empresa_id,array['gerencia','administracion'])) with check(mayorista.operador(empresa_id,array['gerencia','administracion']));
create policy productos_admin_write on mayorista.productos for all to authenticated using(mayorista.operador(empresa_id,array['gerencia','administracion'])) with check(mayorista.operador(empresa_id,array['gerencia','administracion']));
create policy precios_admin_write on mayorista.precios for all to authenticated using(mayorista.operador(empresa_id,array['gerencia','administracion'])) with check(mayorista.operador(empresa_id,array['gerencia','administracion']));
create policy vendedores_admin_write on mayorista.vendedores for all to authenticated using(mayorista.operador(empresa_id,array['gerencia','administracion'])) with check(mayorista.operador(empresa_id,array['gerencia','administracion']));
create policy clientes_admin_write on mayorista.clientes for all to authenticated using(mayorista.operador(empresa_id,array['gerencia','administracion'])) with check(mayorista.operador(empresa_id,array['gerencia','administracion']));
grant select,insert,update on mayorista.rutas,mayorista.listas,mayorista.ofertas,mayorista.objetivos,mayorista.catalog_control,mayorista.productos,mayorista.precios,mayorista.vendedores,mayorista.clientes to authenticated;
rollback;
